def flood_fill_count(grid, value):
    h, w = grid.shape
    visited = np.zeros_like(grid, dtype=bool)
    neighbors = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if visited[cr, cc]:
                continue
            visited[cr, cc] = True
            for dr, dc in neighbors:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not visited[nr, nc] and grid[nr, nc] == value:
                        stack.append((nr, nc))

    components = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] == value and not visited[r, c]:
                dfs(r, c)
                components.append(visited[visited.copy() == True])
    return len(components)

