import numpy as np
from collections import deque
import json

input_grid = np.array([
    [0, 0, 0, 0, 0, 0, 9, 8, 8, 8, 0, 9, 0, 0],
    [0, 8, 0, 0, 0, 0, 0, 0, 9, 0, 0, 0, 0, 0],
    [8, 0, 0, 8, 0, 0, 8, 0, 0, 0, 0, 0, 0, 9],
    [0, 8, 0, 0, 0, 8, 0, 0, 8, 0, 0, 0, 0, 8],
