    [8, 0, 9, 0, 8, 8, 0, 0, 0, 0, 9, 9, 9, 0],
    [0, 9, 8, 0, 0, 8, 0, 0, 0, 0, 0, 0, 0, 0]
])

h, w = 13, 14
visited = np.zeros((h, w), dtype=bool)
clusters_data = []

def get_in_bounds(r, c):
    return 0 <= r < h and 0 <= c < w

def is_inside(r, c):
    return get_in_bounds(r, c) and visited[r, c]

for r in range(h):
    for c in range(w):
        if not visited[r, c] and input_grid[r, c] > 0:
            cluster_cells = []
            stack = [(r, c)]
            cluster_visited = {(r, c)}

            while stack:
                cr, cc = stack.pop()
                cluster_cells.append((cr, cc))
                visited[cr, cc] = True

                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = cr + dr, cc + dc
                    if get_in_bounds(nr, nc):
                        if not is_inside(nr, nc):
                            if input_grid[nr, nc] > 0:
                                cluster_visited.add((nr, nc))
                                stack.append((nr, nc))

            # Track color composition
            color_counts = {8: 0, 9: 0}
            for cr, cc in cluster_cells:
                v = input_grid[cr, cc]
                if v in color_counts:
                    color_counts[v] += 1

            clusters_data.append({
                'cells': cluster_cells,
                'size': len(cluster_cells),
                'color_counts': color_counts,
                'avg_val': sum(input_grid[cr, cc] for cr, cc in cluster_cells) / len(cluster_cells)
            })

print(f"Found {len(clusters_data)} clusters")
for i, clus in enumerate(sorted(clusters_data, key=lambda c: c['size'], reverse=True)):
